20	func (w *failAfterWriter) Write(p []byte) (int, error) {
21		remaining := w.limit - w.written
22		if remaining <= 0 {
23			return 0, errors.New("simulated stdout failure")
24		}
25		if len(p) > remaining {
26			w.buf.Write(p[:remaining])
27			w.written += remaining
28			return remaining, errors.New("simulated stdout failure")
29		}
30		n, _ := w.buf.Write(p)
31		w.written += n
32		return n, nil
33	}
